/**
 * A command list behind a trigger (`design/components/menu.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/menu.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import * as zag from '@zag-js/menu'

import {
  Icon,
  MEMBER_PROVIDERS,
  Portal,
  Ref,
  SlotOutlet,
  SlotTemplate,
  Spread,
  agentMember,
  anchorProps,
  chooseMenuEntry,
  classes,
  derived,
  elementRef,
  followHighlight,
  getters,
  menuChoices,
  mergeParts,
  mountEffect,
  normalizeProps,
  provideOwner,
  setup,
  syncTriggerAnchor,
  uniqueId,
  useDirection,
  useMachine,
  useMediaQuery,
  useMember,
  watchEffect,
  type Each,
  type IconProps,
  type IconRole,
} from '@polymorph/angular'
import { usePresence } from '@polymorph/angular/motion'
import styles from '@polymorph/recipes/overlays/menu.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import triggerAnchor from '@polymorph/recipes/overlays/trigger-anchor.module.css'
import { Kbd } from '../structure/Kbd'
import { MenuSubmenu, type MenuSubmenuProps } from './MenuSubmenu'

export type MenuPresentation = NonNullable<MenuProps['presentation']>

export type MenuAlign = NonNullable<MenuProps['align']>

export interface MenuItemEntry {
  kind?: 'item'
  label: string
  icon?: IconRole
  kbd?: string
  tone?: 'neutral' | 'danger'
  disabled?: boolean
  onSelect: () => void
}

export interface MenuCheckboxEntry {
  kind: 'checkbox'
  label: string
  checked: boolean
  onCheckedChange: (checked: boolean) => void
  disabled?: boolean
}

export interface MenuSeparatorEntry {
  kind: 'separator'
}

export interface MenuLabelEntry {
  kind: 'label'
  label: string
}

export type MenuLeafEntry = MenuItemEntry | MenuCheckboxEntry | MenuSeparatorEntry | MenuLabelEntry

export interface MenuSubmenuEntry {
  kind: 'submenu'
  label: string
  icon?: IconRole
  disabled?: boolean
  items: MenuLeafEntry[]
}

export type MenuEntry = MenuLeafEntry | MenuSubmenuEntry

/** A command list behind a trigger: the inputs it takes, by the React member's prop names. */
export interface MenuProps {
  align?: 'start' | 'end'
  /**
   * Opens on mount, for galleries and tests; screens let the user open it.
   */
  defaultOpen?: boolean
  items: MenuEntry[]
  /**
   * The controlled pair; uncontrolled is the default. Use it to keep the menu open across
   * several checkbox toggles, or to close it on "apply".
   */
  open?: boolean
  /**
   * `'auto'` uses a sheet below `30rem` (the sheet presentation, `design/components/README.md`),
   * the phone's standard pattern for "choose from these". `'popover'` keeps the popper at every
   * width, for the rare pointer-first embed that needs precision. There is no always-`'sheet'`
   * value, because a bottom sheet does not suit a wide pointer surface, and the closed union
   * rejects it (`docs/layout.md`).
   */
  presentation?: 'auto' | 'popover'
}

/** What Menu hands its compound parts. */
export interface MenuOwner {
  readonly api: zag.Api
  readonly service: zag.Service
}

/** A command list behind a trigger. */
